    $a = (int)$parts[0] - 1;
    $b = (int)$parts[1] - 1;
    $adj[$a][] = $b;
    $radj[$b][] = $a;
}

// Step 1: Find all nodes that can reach a "use" node (f[i] == 2)
// We do BFS/DFS on the reverse graph starting from all use nodes.
$canReachUse = array_fill(0, $n, false);
$queue = array();
for ($i = 0; $i < $n; $i++) {
    if ($f[$i] == 2) {
        $canReachUse[$i] = true;
        $queue[] = $i;
    }
}
$head = 0;
while ($head < count($queue)) {
    $u = $queue[$head++];
    foreach ($radj[$u] as $v) {
        if (!$canReachUse[$v]) {
            $canReachUse[$v] = true;
            $queue[] = $v;
        }
    }
}

// Step 2: Find all nodes that can be reached from an "assign" node (f[i] == 1)
// We do BFS/DFS on the forward graph starting from all assign nodes.
$canReachFromAssign = array_fill(0, $n, false);
$queue = array();
for ($i = 0; $i < $n; $i++) {
    if ($f[$i] == 1) {
        $canReachFromAssign[$i] = true;
        $queue[] = $i;
    }
}
$head = 0;
while ($head < count($queue)) {
    $u = $queue[$head++];
    foreach ($adj[$u] as $v) {
        if (!$canReachFromAssign[$v]) {
            $canReachFromAssign[$v] = true;
            $queue[] = $v;
        }
    }
}

// Step 3: For a node to be "interesting", it must:
// - Be reachable from some assign node (canReachFromAssign[i] is true)
// - Be able to reach some use node (canReachUse[i] is true)
// - AND on the path from assign to use through this node, there should be no other assign node between the starting assign and this node (exclusive of the start).
// 
